package com.flashsale.service;
import com.flashsale.config.KafkaConfig; import com.flashsale.dto.*; import com.flashsale.messaging.OrderEvent; import java.util.UUID; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Service;
@Service public class PurchaseService { private final InventoryService inventory; private final KafkaTemplate<String,OrderEvent> kafka; public PurchaseService(InventoryService inventory,KafkaTemplate<String,OrderEvent> kafka){this.inventory=inventory;this.kafka=kafka;} public PurchaseResponse purchase(PurchaseRequest request,String key){long outcome=inventory.reserve(request.productId(),key);if(outcome==-1)return new PurchaseResponse(null,"DUPLICATE","This request was already accepted.");if(outcome==0)return new PurchaseResponse(null,"SOLD_OUT","This product is sold out.");UUID id=UUID.randomUUID();kafka.send(KafkaConfig.ORDER_TOPIC,request.productId(),new OrderEvent(id,request.productId(),request.customerId(),key));return new PurchaseResponse(id,"ACCEPTED","Your order is being processed.");} }
